/* @author MILO-GAO(高振銘)@2020 */ package page2020.anno;import java.lang.reflect.Field;import java.math.BigDecimal;import java.util.Date;import page2020.util.EmptyUtil;public class ColItem extends DataItem<ColItem> {	private Col2020 anno;	private String pattern;	private String format;	private String erase;	private boolean wrap;	private String color;	private String background;	private boolean bold;	private boolean italic;	private String width;	private int align;	private String dollar;	public ColItem(Field field, String className, String topClassName) {		super(field, className, topClassName);		Col2020 anno = null;		if (field.isAnnotationPresent(Col2020.class)) {			field.setAccessible(true);			anno = field.getAnnotation(Col2020.class);			super.anno(anno.name(), anno.index(), anno.key(), anno.hidden());		} else {			return;		}		this.anno = anno;		this.pattern = anno.pattern();		this.format = anno.format();		this.erase = anno.erase();		this.wrap = anno.wrap();		this.color = anno.color();		this.background = anno.background();		this.bold = anno.bold();		this.italic = anno.italic();		this.width = anno.width();		this.align = anno.align();		this.dollar = anno.dollar();		Class<?> clazz = field.getType();		if (EmptyUtil.is(this.pattern)) {			if (clazz.equals(Byte.class) ||				clazz.equals(Short.class) ||				clazz.equals(Integer.class) ||				clazz.equals(Long.class) ||				clazz.equals(Float.class) ||				clazz.equals(Double.class) ||				clazz.equals(BigDecimal.class)) {				this.pattern = Pattern.number;			} else if (clazz.equals(Date.class)) {				this.pattern = Pattern.date;			}		}		if (EmptyUtil.not(this.pattern) && EmptyUtil.is(this.format)) {			switch (this.pattern) {			case Pattern.number:				if (clazz.equals(Byte.class) || clazz.equals(Short.class)) {					this.format = "0";				} else if (clazz.equals(Integer.class) || clazz.equals(Long.class)) {					this.format = "#,##0";				} else if (clazz.equals(Float.class)) {					this.format = "#,##0.00";				} else if (clazz.equals(Double.class)) {					this.format = "#,##0.0000";				} else if (clazz.equals(BigDecimal.class)) {					this.format = "#,##0.000000";				}								break;			case Pattern.date:				this.format = "yyyy/MM/dd";				break;			case Pattern.time:				this.format = "HH:mm:ss";				break;			case Pattern.datetime:				this.format = "yyyy/MM/dd HH:mm:ss";				break;			}		}		if (Pattern.number.equals(this.pattern)) {			if (this.align == -1) {				this.align = 1;			}			if (clazz.equals(BigDecimal.class) && EmptyUtil.is(this.dollar)) {				this.dollar = "$";			}		}	}	@Override	public String toString() {		return "ColItem [pattern=" + pattern + ", format=" + format + ", color=" + color + ", background=" + background				+ ", bold=" + bold + ", italic=" + italic + ", width=" + width + ", align=" + align + ", dollar="				+ dollar + ", getClassName()=" + getClassName() + ", getFieldName()=" + getFieldName() + ", getIndex()="				+ getIndex() + ", isKey()=" + isKey() + ", isHidden()=" + isHidden() + ", getName()=" + getName() + "]";	}	public Col2020 getAnno() {		return anno;	}	public String getPattern() {		return pattern;	}	public String getFormat() {		return format;	}	public String getErase() {		return erase;	}	public boolean isWrap() {		return wrap;	}	public String getColor() {		return color;	}	public void setColor(String color) {		this.color = color;	}	public String getBackground() {		return background;	}	public void setBackground(String background) {		this.background = background;	}	public boolean isBold() {		return bold;	}	public void setBold(boolean bold) {		this.bold = bold;	}	public boolean isItalic() {		return italic;	}	public void setItalic(boolean italic) {		this.italic = italic;	}	public String getWidth() {		return width;	}	public void setWidth(String width) {		this.width = width;	}	public int getAlign() {		return align;	}	public void setAlign(int align) {		this.align = align;	}	public String getDollar() {		return dollar;	}	public void setDollar(String dollar) {		this.dollar = dollar;	}}